{"path":"tools/LetUsCook.AutoWrongCensus/AutoWrongCensusCli.cs","content":"using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point. <c>Program.cs</> delegates to <see cref="RunAsync"/> so the test
/// project can drive the exact same host graph with captured writers.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs the census CLI to completion and returns the process exit code.</summary>
	/// <param name="args">The raw command-line arguments.</param>
	/// <param name="output">The writer for the TSV (defaults to <see cref="System.Console.Out"/>).</param>
	/// <param name="error">The writer for the summary and errors (defaults to <see cref="System.Console.Error"/>).</param>
	public static async Task<int> RunAsync(string[] args, TextWriter? output = null, TextWriter? error = null)
	{
		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		var host = builder.Build();

		// Resolve BEFORE RunAsync(): RunAsync disposes the provider on shutdown.
		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync().ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
