/// <summary>
/// One classified auto-wrong line — the census TSV row plus the stderr-only extras (qualifier
/// difference for <c>same-head-other-qualifier</c>, tier direction for <c>row-choice-tier</c>,
/// and the missing-field name when the relation fell to <c>other</c> for lack of a trace field).
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>The holdout row id.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>The line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>The trace set.</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>The accepted-row vs key-row relation (one of the eight classes).</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>The decision site: <c>reuse</c>, <c>override</c>, <c>curated</c>, or <c>ranker</c>. Null when the atom's path was unrecognised.</summary>
	public string? Site { get; init; }

	/// <summary>For <c>override</c> sites: <c>yes</c>/<c>no</c> — whether the normalised rawText is a key in <c>exact-overrides.json</c>.</summary>
	public string? OverrideKey { get; init; }

	/// <summary>The accepted row's dataset tier.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>The key row's dataset tier.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>The accepted row's combined state mask (production <c>ExtractCandidateState | ExtractCandidateSatisfiers</c>).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>The key row's combined state mask.</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key row's head phrase (head term plus the leading non-state qualifier words), singularised.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>The accepted row description.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>The key row description.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line text.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>For <c>same-head-other-qualifier</c>: the qualifier difference, human-readable.</summary>
	public string? QualifierDiff { get; init; }

	/// <summary>For <c>row-choice-tier</c>: <c>key</c> or <c>accepted</c> — which tier is higher.</summary>
	public string? TierDirection { get; init; }

	/// <summary>When the relation is <c>other</c> because a trace field was missing: the field name.</summary>
	public string? MissingField { get; init; }
}
