{"content":"using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the relation between the accepted row
/// (<c>actual*[0]</c>) and the labelled key row (<c>expected*[0]</c>), and the decision site that
/// accepted it. Every comparison goes through the production helpers (F-428 D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens"/> for tokens, <see cref="FdcMatcher.ExtractCandidateState"/>
/// and <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> for the <see cref="FoodState"/> masks,
/// <see cref="FdcDescriptionParser.Parse"/> for head terms, and
/// <see cref="IngredientLineResolver.SingularizeToken"/> for singular folding.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw line, the key carries <see cref="FoodState.Canned"/> and the accepted row does not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key's head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the <see cref="FoodState"/> masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: head terms and state agree and the dataset tier differs.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head terms agree and nothing above holds — a qualifier difference.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: no rule matched, or a field the rule needs is missing from the trace.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state probes (CA1861: no constant-array arguments).
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production token normalizer.</param>
	/// <param name="overrideKeys">The exact-overrides.json key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Classifies one auto-wrong line; the first relation that holds wins (brief §4 order).</summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification, or <see langword="null"/> when the atom carries an unknown decision path.</returns>
	public ClassificationResult? Classify(TraceLine line)
	{
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();
		if (atom is null)
		{
			return null;
		}

		var (site, overrideKey) = SiteOf(atom);
		if (site is null)
		{
			return null;
		}

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault();
		var accDesc = line.ActualDescriptions.FirstOrDefault();
		var keyType = line.ExpectedDataTypes.FirstOrDefault();
		var accType = line.ActualDataTypes.FirstOrDefault();
		var keyTypeS = keyType ?? string.Empty;
		var accTypeS = accType ?? string.Empty;

		var relation = RelationOther;
		var missingField = string.Empty;
		var keyHeadPhrase = string.Empty;
		var qualifierDiff = string.Empty;
		var tierDirection = string.Empty;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = RelationNoLabel;
		}
		else
		{
			var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
			var accTokens = _normalizer.NormalizeToTokens(accDesc);
			var keyState = CombinedState(keyTokens);
			var accState = CombinedState(accTokens);
			var keyHead = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTypeS)).HeadTerm;
			var accHead = string.IsNullOrWhiteSpace(accDesc)
				? string.Empty
				: FdcDescriptionParser.Parse(accDesc, DatasetOf(accTypeS)).HeadTerm;
			var keyHeadNorm = SingularPhrase(keyHead);
			var accHeadNorm = SingularPhrase(accHead);
			var parsedNameNorm = SingularPhrase(atom.ParsedName);
			keyHeadPhrase = string.Join(' ', KeyHeadPhrase(keyTokens));

			if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (accState & FoodState.Canned) == 0)
			{
				relation = RelationPackUnitState;
			}
			else if (keyHeadPhrase.Count >= 2 && parsedNameNorm.Count == 1
				&& string.Equals(parsedNameNorm[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
			{
				relation = RelationCompoundHeadLost;
			}
			else if (keyHeadNorm.SequenceEqual(accHeadNorm, StringComparer.OrdinalIgnoreCase))
			{
				if (keyState != accState)
				{
					relation = RelationStateMismatch;
				}
				else if (string.IsNullOrWhiteSpace(keyTypeS) || string.IsNullOrWhiteSpace(accTypeS))
				{
					relation = RelationOther;
					missingField = string.IsNullOrWhiteSpace(accTypeS) ? "actualDataTypes" : "expectedDataTypes";
				}
				else if (!string.Equals(keyTypeS, accTypeS, StringComparison.OrdinalIgnoreCase))
				{
					relation = RelationRowChoiceTier;
					tierDirection = TierRank(keyTypeS) > TierRank(accTypeS) ? "key-higher" : "accepted-higher";
				}
				else
				{
					relation = RelationSameHeadOtherQualifier;
					qualifierDiff = QualifierDiff(keyDesc, keyTypeS, accDesc, accTypeS);
				}
			}
			else
			{
				relation = RelationSiblingFood;
			}
		}

		return new ClassificationResult(
			line.HoldoutId,
			line.LineIndex,
			line.Set,
			relation,
			site,
			overrideKey,
			accTypeS,
			keyTypeS,
			StateText(line, accDesc),
			StateText(line, keyDesc),
			atom.ParsedName,
			keyHeadPhrase,
			accDesc ?? string.Empty,
			keyDesc ?? string.Empty,
			line.RawText,
			missingField,
			qualifierDiff,
			tierDirection);
	}

	/// <summary>
	/// The key's head phrase: the leading normalized tokens of the key description, stopping before the
	/// first token the production state machinery recognises as a state word (a
	/// <see cref="FdcLexicon.ModifierWords"/> member or a token the production
	/// <see cref="FdcMatcher.ExtractCandidateState"/>/<see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// probe reports non-<see cref="FoodState.None"/> for). "Bread, crumbs, dry, grated, plain" yields
	/// [bread, crumbs]; "Nuts, almonds, blanched" yields [nut, almond].
	/// </summary>
	/// <param name="keyTokens">The production-normalized tokens of the key description.</param>
	/// <returns>The head-phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The production state mask for a description: <c>ExtractCandidateState | ExtractCandidateSatisfiers</c> on its tokens.</summary>
	/// <param name="description">The description to mask.</param>
	/// <returns>The combined mask.</returns>
	public FoodState CombinedStateOf(string? description) => CombinedState(_normalizer.NormalizeToTokens(description));

	/// <summary>
	/// The resolver's own exact-phrase reuse rule (F-428 P6.6) applied to the atom's parsed name and its
	/// linked master slug: <c>true</c> when the phrase the line parsed is token-for-token the master it
	/// reused. Summary statistic only — never a relation input.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>The production <see cref="IngredientLineResolver.ShouldReuse"/> verdict.</returns>
	public bool ReusePhraseAgrees(string parsedName, string linkedIngredientId)
	{
		var slug = IngredientLineParser.ComputeSlug(parsedName);
		return slug.Length > 0 && IngredientLineResolver.ShouldReuse(slug, linkedIngredientId);
	}

	private static (string? Site, string? OverrideKey) SiteOf(TraceAtom atom)
	{
		if (atom.Path.Equals("override", StringComparison.OrdinalIgnoreCase))
		{
			return (SiteOverride, null);
		}

		if (atom.Path.Equals("curated", StringComparison.OrdinalIgnoreCase))
		{
			return (SiteCurated, null);
		}

		if (atom.Path.Equals("ranker", StringComparison.OrdinalIgnoreCase))
		{
			return atom.Reused ? (SiteReuse, null) : (SiteRanker, null);
		}

		return (null, null);
	}

	private static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private static FdcDataset DatasetOf(string dataType) =>
		Enum.TryParse<FdcDataset>(dataType, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static int TierRank(string dataType) => dataType switch
	{
		"Foundation" => 4,
		"Survey" => 3,
		"SrLegacy" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private IReadOnlyList<string> SingularPhrase(string text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private string StateText(TraceLine line, string? description)
	{
		_ = line;
		return CombinedState(_normalizer.NormalizeToTokens(description)).ToString();
	}

	private string QualifierDiff(string keyDesc, string keyType, string accDesc, string accType)
	{
		var keyQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType)).Qualifiers);
		var accQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(accDesc, DatasetOf(accType)).Qualifiers);
		var keyOnly = keyQualifiers.Except(accQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(w => w, StringComparer.Ordinal).ToArray();
		var accOnly = accQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(w => w, StringComparer.Ordinal).ToArray();
		return $"key-only=[{string.Join(", ", keyOnly)}] accepted-only=[{string.Join(", ", accOnly)}]";
	}

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> qualifiers) =>
		qualifiers.Select(IngredientLineResolver.SingularizeToken).ToArray();
}
