{"content":"using System.Text.Json;
using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The key set of the shipped <c>exact-overrides.json</c> (embedded in LetUsCook.Fdc), loaded once.
/// The file is data, not matcher logic — the census only asks whether a normalized raw line is one
/// of its keys (F-428 P12.13 brief §4, site <c>override</c>).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the embedded <c>exact-overrides.json</c> keys.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), JsonOptions)
			?? throw new InvalidOperationException("exact-overrides.json was empty.");
		_keys = FrozenSet.ToFrozenSet(entries.Keys, StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Number of keys in <c>exact-overrides.json</c>.</summary>
	public int Count => _keys.Count;

	/// <summary>Whether <paramref name="key"/> is a key of <c>exact-overrides.json</c> (case-insensitive).</summary>
	/// <param name="key">A normalized raw line.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
