{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line (F-428 P12.13): the accepted row vs the key row relation
/// (first rule that holds wins) and the decision site. Every food-shape decision goes through the
/// production helpers (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and
/// <see cref="IngredientLineResolver.ShouldReuse(string, string)"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the line has no labelled row.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, the key row is Canned and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head and state agree, tiers agree, the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held (including a missing trace field a check needed).</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line came from the exact/special-case override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line came from the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the line was matched by the ranker without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list so the per-token production state calls never allocate (the census
	// scans every token of every key description; the runner is single-threaded).
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier over the production normalizer and the exact-override key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The exact-override raw-key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Classifies one auto-wrong line.</summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var linkedIngredientId = atom?.LinkedIngredientId;

		var (site, overrideKey) = ClassifySite(atom?.Path, line.RawText, parsedName, linkedIngredientId);
		if (site.Length == 0)
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = Other,
				Site = string.Empty,
				ParsedName = parsedName,
				AcceptedDesc = acceptedDesc,
				KeyDesc = keyDesc,
				RawText = line.RawText,
			};
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = acceptedDesc.Length > 0
			? SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm)
			: [];
		var parsedTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var relation = Other;
		var missingField = (string?)null;
		IReadOnlyList<string>? keyOnly = null;
		IReadOnlyList<string>? acceptedOnly = null;

		if (keyDesc.Length == 0)
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedTokens.Count == 1
			&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (HeadTermsAgree(keyHead, acceptedHead))
		{
			if (keyState != acceptedState)
			{
				relation = StateMismatch;
			}
			else if (keyTier.Length == 0 || acceptedTier.Length == 0)
			{
				relation = Other;
				missingField = keyTier.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
				var keyQualifiers = QualifierPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)));
				var acceptedQualifiers = acceptedDesc.Length > 0
					? QualifierPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)))
					: [];
				keyOnly = SetDifference(keyQualifiers, acceptedQualifiers);
				acceptedOnly = SetDifference(acceptedQualifiers, keyQualifiers);
			}
		}
		else
		{
			relation = SiblingFood;
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnly,
			AcceptedOnlyQualifiers = acceptedOnly,
		};
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to the first token the
	/// production state/modifier vocabulary marks as a state or modifier word. A two-or-more-word
	/// phrase whose first word is the whole parsed name is the compound-head-lost shape (F-428 P12.13 §2).
	/// </summary>
	/// <param name="keyTokens">Normalized key description tokens.</param>
	/// <returns>The head phrase tokens (possibly one or zero words).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>();
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/>
	/// union <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition
	/// <c>FdcMatcher.StateAgrees</c> consumes.
	/// </summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The combined state mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The resolver's own exact-phrase reuse verdict for a parsed name against its linked master slug
	/// (stderr summary statistic for reuse-site lines).
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns><see langword="true"/> when the production rule would reuse that master for the name.</returns>
	public bool ProductionReuseAgrees(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		var slug = IngredientLineParser.ComputeSlug(parsedName);
		return slug.Length > 0 && IngredientLineResolver.ShouldReuse(slug, linkedIngredientId);
	}

	private (string Site, string OverrideKey) ClassifySite(string? path, string rawText, string parsedName, string? linkedIngredientId)
	{
		if (path is null)
		{
			return (string.Empty, string.Empty);
		}

		if (path.Equals("override", StringComparison.OrdinalIgnoreCase))
		{
			var isKey = _overrideKeys.IsKey(NormalizeForOverrideKey(rawText)) || _overrideKeys.IsKey(rawText.Trim().ToLowerInvariant());
			return (SiteOverride, isKey ? "yes" : "no");
		}

		if (path.Equals("curated", StringComparison.OrdinalIgnoreCase))
		{
			return (SiteCurated, string.Empty);
		}

		if (path.Equals("ranker", StringComparison.OrdinalIgnoreCase))
		{
			_ = parsedName;
			_ = linkedIngredientId;
			return (SiteRanker, string.Empty);
		}

		return (string.Empty, string.Empty);
	}

	/// <summary>Folds a raw line for the exact-override raw-key lookup: lower-cased, trimmed, content from the first <c>(</c> dropped (the production lookup's own fold).</summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded key candidate.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var lowered = rawText.Trim().ToLowerInvariant();
		var parenIndex = lowered.IndexOf('(', StringComparison.Ordinal);
		return (parenIndex >= 0 ? lowered[..parenIndex] : lowered).Trim();
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> QualifierPhrase(ParsedFdcDescription parsed) =>
		parsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static bool HeadTermsAgree(IReadOnlyList<string> keyHead, IReadOnlyList<string> acceptedHead) =>
		keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true) ? Enum.Parse<FdcDataset>(tier, ignoreCase: true) : FdcDataset.None;

	private static IReadOnlyList<string> SetDifference(IReadOnlyList<string> left, IReadOnlyList<string> right)
	{
		var rightSet = new HashSet<string>(right, StringComparer.OrdinalIgnoreCase);
		return left.Where(t => !rightSet.Contains(t)).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
	}

	private bool IsStateOrModifierWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}
}
