{"content":"using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;
using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the relation between the accepted row and
/// the labelled (key) row, and the decision site — using the production helpers, never copies of
/// them (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse"/>, <see cref="IngredientLineResolver.ShouldReuse"/> and
/// <see cref="IngredientLineResolver.SingularizeToken"/>.
/// <para>
/// Relation ladder (first hit wins): <c>no-label</c>, <c>pack-unit-state</c>, <c>compound-head-lost</c>,
/// <c>state-mismatch</c>, <c>row-choice-tier</c>, <c>same-head-other-qualifier</c>, <c>
/// sibling-food</c>, <c>other</c>. A line whose relation check needs a trace field that is missing
/// is <c>other</c> with <see cref="ClassificationResult.MissingField"/> naming the field (brief §8).
/// </para>
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key row has no label.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit line accepted on a fresh (non-canned) row while the key is canned.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key names a multi-word head and the parsed name kept only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: same head, different state masks.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: same head and state, different dataset tier.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: same head, state and tier; only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the heads differ — a different food.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a needed trace field is missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing master row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line went through the exact/mint override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line went through the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker picked the row without reuse.</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Trace sets the census accepts; every other value is refused (D-029).</summary>
	public static readonly FrozenSet<string> AllowedSets = FrozenSet.ToFrozenSet(["debug", "batch"], StringComparer.Ordinal);

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused for the single-token state probes so the ladder allocates nothing per token. The
	// runner classifies lines sequentially; the classifier is not thread-safe by design.
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates the classifier over the production normalizer and the exact-override key set.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The exact-override key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Classifies one auto-wrong line. The caller guarantees <c>auto == true &amp;&amp; correct == false</c>.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			ParsedName = parsedName,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (atom is null || !KnownPath(atom.Path))
		{
			return result;
		}

		result.Site = atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => atom.Reused ? SiteReuse : SiteRanker,
		};
		if (result.Site == SiteOverride)
		{
			result.OverrideKey = _overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no";
		}

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result.KeyState = keyState.ToString();
		result.AcceptedState = acceptedState.ToString();

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		result.KeyHead = string.Join(' ', keyHead);
		var parsedNameTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			result.Relation = PackUnitState;
			return result;
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		if (HeadAgrees(keyHead, acceptedHead))
		{
			if (keyState != acceptedState)
			{
				result.Relation = StateMismatch;
				return result;
			}

			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				result.Relation = Other;
				result.MissingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
				return result;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				result.Relation = RowChoiceTier;
				return result;
			}

			result.Relation = SameHeadOtherQualifier;
			(result.KeyOnlyQualifiers, result.AcceptedOnlyQualifiers) = QualifierDifference(
				FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers,
				FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
			return result;
		}

		result.Relation = SiblingFood;
		return result;
	}

	/// <summary>
	/// The key head phrase: the normalized key tokens up to (excluding) the first token the
	/// production state/modifier vocabulary marks as state-carrying — <c>Bread, crumbs, dry,
	/// grated, plain</c> yields <c>[bread, crumbs]</c>, <c>Tomatoes, crushed, canned</c> yields
	/// <c>[tomato]</c>. Deterministic per key description, so the same key classifies the same in
	/// every recipe.
	/// </summary>
	/// <param name="keyTokens">The normalized key description tokens.</param>
	/// <returns>The head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The state mask production uses for a candidate: <see cref="FdcMatcher.ExtractCandidateState"/> ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>.</summary>
	/// <param name="tokens">The normalized description tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Folds a raw line the way the production override lookup folds it
	/// (<c>FdcMatcher.MatchAsync</c>: cut at the first <c>(</c>, trim, lower-case) — the cut itself is
	/// <c>FdcMatcher</c>'s private <c>StripFromParenthesis</c>, applied here as the same one-line rule
	/// because the private method is unreachable (brief §8).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var cut = rawText.IndexOf('(', StringComparison.Ordinal);
		var text = cut >= 0 ? rawText[..cut] : rawText;
		return text.Trim().ToLowerInvariant();
	}

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>)
	/// would match the line's computed slug to the master slug it actually linked to.
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug, or null.</param>
	/// <returns>True when the rule matches; false when either side is empty or the rule rejects.</returns>
	public static bool ReuseRuleMatches(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(parsedName) || string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	private static bool KnownPath(string path) =>
		path.Equals("ranker", StringComparison.OrdinalIgnoreCase)
		|| path.Equals("override", StringComparison.OrdinalIgnoreCase)
		|| path.Equals("curated", StringComparison.OrdinalIgnoreCase);

	private static bool HeadAgrees(IReadOnlyList<string> a, IReadOnlyList<string> b) =>
		a.Count == b.Count && a.Zip(b).All(p => string.Equals(p.First, p.Second, StringComparison.OrdinalIgnoreCase));

	private static string First(IReadOnlyList<string> list) =>
		list.Count > 0 ? list[0] : string.Empty;

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private (IReadOnlyList<string> KeyOnly, IReadOnlyList<string> AcceptedOnly) QualifierDifference(
		IReadOnlyList<string> keyQualifiers,
		IReadOnlyList<string> acceptedQualifiers)
	{
		var keySet = new HashSet<string>(keyQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedQualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var keyOnly = keySet.Where(q => !acceptedSet.Contains(q)).OrderBy(q => q, StringComparer.Ordinal).ToArray();
		var acceptedOnly = acceptedSet.Where(q => !keySet.Contains(q)).OrderBy(q => q, StringComparer.Ordinal).ToArray();
		return (keyOnly, acceptedOnly);
	}

	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}
}
