{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.AutoWrongCensus.Services;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus;

/// <summary>One invocation's stdout/stderr sinks.</summary>
/// <param name="Output">TSV sink.</param>
/// <param name="Error">Summary and diagnostics sink.</param>
public sealed record OutputSinks(System.IO.TextWriter Output, System.IO.TextWriter Error);

/// <summary>
/// Runs one census or pairs invocation: reads the trace, refuses any non-debug/batch set (D-029),
/// classifies every <c>auto &amp;&amp; !correct</c> line through the production-backed
/// <see cref="AutoWrongClassifier"/> and writes the TSV to stdout plus the relation × site summary
/// to stderr.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer,
	OutputSinks sinks) : IAutoWrongCensusRunner
{
	private static readonly System.Text.Json.JsonSerializerOptions JsonOptions = new(System.Text.Json.JsonSerializerDefaults.Web);

	private const string CensusHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <summary>Runs the invocation and returns the exit code (0 success, 1 failure).</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or a malformed invocation.</returns>
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var opts = options.Value;

		if (string.IsNullOrEmpty(opts.Command))
		{
			sinks.Error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
			return 1;
		}

		if (!System.IO.File.Exists(opts.TracePath))
		{
			sinks.Error.WriteLine($"trace file not found at '{opts.TracePath}'.");
			return 1;
		}

		var lines = await Task.Run(() => ReadTrace(opts.TracePath), cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Where(l => !l.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !l.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			.Select(l => l.Set)
			.Distinct(StringComparer.OrdinalIgnoreCase)
			.ToList();
		if (refused.Count > 0)
		{
			sinks.Error.WriteLine($"refusing trace set '{string.Join("', '", refused)}': only debug and batch traces are classified (D-029).");
			return 1;
		}

		return opts.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: await RunPairsAsync(lines, cancellationToken).ConfigureAwait(false);
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();

		sinks.Output.WriteLine(CensusHeader);
		foreach (var line in autoWrong)
		{
			ClassificationResult result;
			try
			{
				result = classifier.Classify(line);
			}
			catch (InvalidOperationException ex)
			{
				sinks.Error.WriteLine(ex.Message);
				return 1;
			}

			if (result.Site.Length == 0)
			{
				sinks.Error.WriteLine($"unknown atom path '{AtomPath(line)}' on {line.HoldoutId}#{line.LineIndex}; refusing to classify it.");
				return 1;
			}

			sinks.Output.WriteLine(ToTsvRow(result));
		}

		WriteSummary(lines, autoWrong);
		return 0;
	}

	private async Task<int> RunPairsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (!System.IO.File.Exists(opts.CensusTsvPath))
		{
			sinks.Error.WriteLine($"census TSV not found at '{opts.CensusTsvPath}'.");
			return 1;
		}

		var wanted = await Task.Run(() => ReadWantedRows(opts.CensusTsvPath), cancellationToken).ConfigureAwait(false);
		if (wanted is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		sinks.Output.WriteLine(PairsHeader);

		var emitted = 0;
		var missing = 0;
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				missing++;
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null ? string.Empty : string.Join(' ', SingularTokens(normalizer, atom.ParsedName));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty)));
			sinks.Output.WriteLine($"{Sanitize(holdoutId)}\t{lineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		sinks.Error.WriteLine($"pairs set={lines.Count > 0 ? lines[0].Set : "?"} wanted={wanted.Count} emitted={emitted} missingInTrace={missing}");
		return 0;
	}

	private void WriteSummary(IReadOnlyList<TraceLine> lines, List<TraceLine> autoWrong)
	{
		var set = lines.Count > 0 ? lines[0].Set : "?";
		sinks.Error.WriteLine($"autoWrongCensus set={set} lines={lines.Count} autoWrong={autoWrong.Count}");
		sinks.Error.WriteLine("relation\tsite\tcount");

		var results = new List<ClassificationResult>(autoWrong.Count);
		foreach (var line in autoWrong)
		{
			results.Add(classifier.Classify(line));
		}

		foreach (var (relation, site) in results.Select(r => (r.Relation, r.Site)).OrderBy(p => p.Item1).ThenBy(p => p.Item2))
		{
			var count = results.Count(r => r.Relation == relation && r.Site == site);
			sinks.Error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		sinks.Error.WriteLine($"other={otherCount} ({(autoWrong.Count > 0 ? otherCount * 100.0 / autoWrong.Count : 0.0):F1}%)");

		var missingFields = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key).ToList();
		sinks.Error.WriteLine(missingFields.Count == 0
			? "missing fields: none"
			: "missing fields: " + string.Join(", ", missingFields.Select(g => $"{g.Key}={g.Count()}")));

		var overrideSite = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		sinks.Error.WriteLine($"override-site lines: {overrideSite.Count}, rawText is an exact-overrides.json key: {overrideSite.Count(r => r.OverrideKey == "yes")}");

		var reuseSite = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseChecked = 0;
		var reuseFalse = 0;
		foreach (var line in autoWrong.Where(l => AtomPath(l) == "ranker"))
		{
			var atom = FirstAcceptedAtom(l);
			if (atom is null || atom.LinkedIngredientId is null)
			{
				continue;
			}

			reuseChecked++;
			if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
			{
				reuseFalse++;
			}
		}
		sinks.Error.WriteLine($"reuse-site lines: {reuseSite.Count}, ShouldReuse(parsedName, linkedIngredientId) false: {reuseFalse} of {reuseChecked}");

		var tierRows = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierRows.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		sinks.Error.WriteLine($"row-choice-tier: {tierRows.Count} lines, key tier higher: {keyHigher}, accepted tier higher: {tierRows.Count - keyHigher}");

		var qualifierRows = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier).ToList();
		sinks.Error.WriteLine($"same-head-other-qualifier: {qualifierRows.Count} lines");
		foreach (var r in qualifierRows)
		{
			sinks.Error.WriteLine($"  {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static IReadOnlyList<TraceLine> ReadTrace(string path)
	{
		var lines = new List<TraceLine>();
		foreach (var raw in System.IO.File.ReadLines(path))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			var line = System.Text.Json.JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
			if (line is null)
			{
				return null;
			}

			lines.Add(line);
		}

		return lines;
	}

	private static List<(string HoldoutId, int LineIndex)>? ReadWantedRows(string path)
	{
		var wanted = new List<(string, int)>();
		var header = System.IO.File.ReadLines(path).FirstOrDefault()?.Split('\t');
		if (header is null)
		{
			return null;
		}

		var holdoutId = Array.IndexOf(header, "holdoutId");
		var lineIndex = Array.IndexOf(header, "lineIndex");
		var blocker = Array.IndexOf(header, "blocker");
		var route = Array.IndexOf(header, "route");
		if (holdoutId < 0 || lineIndex < 0 || blocker < 0 || route < 0)
		{
			return null;
		}

		foreach (var raw in System.IO.File.ReadLines(path).Skip(1))
		{
			var cells = raw.Split('\t');
			if (cells.Length <= Math.Max(Math.Max(holdoutId, lineIndex), Math.Max(blocker, route)))
			{
				continue;
			}

			if (cells[blocker].Equals("window", StringComparison.Ordinal)
				&& (cells[route].Equals("compound", StringComparison.Ordinal) || cells[route].Equals("other", StringComparison.Ordinal))
				&& int.TryParse(cells[lineIndex], out var idx))
			{
				wanted.Add((cells[holdoutId], idx));
			}
		}

		return wanted;
	}

	private static string AtomPath(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0].Path : string.Empty;

	private static TraceAtom? FirstAcceptedAtom(TraceLine line)
	{
		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return line.Atoms.Count > 0 ? line.Atoms[0] : null;
	}

	private static IReadOnlyList<string> SingularTokens(FdcNormalizer normalizer, string? text)
	{
		var tokens = normalizer.NormalizeToTokens(text);
		return System.Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));
	}

	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
