{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs one <c>census</c> or <c>pairs</c> invocation. Reads the trace once, refuses any record whose
/// <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029), then classifies every
/// <c>auto == true &amp;&amp; correct == false</c> line. TSV goes to the output sink; the relation × site
/// summary and every diagnostic go to the error sink.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly string[] TsvHeader =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey", "acceptedTier", "keyTier",
		"acceptedState", "keyState", "parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			AutoWrongCensusUsage.Print();
			return 1;
		}

		var lines = await ReadTraceAsync(cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		if (RefusedSet(lines) is { } refused)
		{
			Error($"refused: trace record set '{refused}' is not debug or batch (D-029); no sealed read, ever.");
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: RunPairs(lines);
	}

	/// <summary>Classifies every auto-wrong line of the trace; TSV to stdout, summary to stderr.</summary>
	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);

		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				Error($"refused: unknown atom path '{AtomPathOf(line)}' on {line.HoldoutId}#{line.LineIndex}; the census refuses to guess a site.");
				return 1;
			}

			results.Add(result);
		}

		WriteTsv(results);
		WriteSummary(lines, results);
		return 0;
	}

	/// <summary>Joins the P12.7 census rows (blocker=window, route compound/other) with the trace.</summary>
	private int RunPairs(IReadOnlyList<TraceLine> lines)
	{
		var censusRows = ReadCensusTsv();
		if (censusRows is null)
		{
			return 1;
		}

		var byLine = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var pairs = 0;

		Output(string.Join('\t', "holdoutId", "lineIndex", "parsedNameHead", "keyHead", "rawText"));
		foreach (var row in censusRows)
		{
			if (!byLine.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				Error($"pairs: census row {row.HoldoutId}#{row.LineIndex} has no matching trace line; skipped.");
				continue;
			}

			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(keyDesc)));
			var parsedNameHead = string.Join(' ', FoldName(line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty));
			Output(string.Join('\t', Sanitize(row.HoldoutId), row.LineIndex, Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
			pairs++;
		}

		Error($"pairs: {pairs} window compound/other rows emitted from {censusRows.Count} census rows.");
		return 0;
	}

	private void WriteTsv(IReadOnlyList<ClassificationResult> results)
	{
		Output(string.Join('\t', TsvHeader));
		foreach (var r in results)
		{
			Output(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex,
				Sanitize(r.Set),
				r.Relation,
				r.Site,
				r.OverrideKey,
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				r.AcceptedState,
				r.KeyState,
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteSummary(IReadOnlyList<TraceLine> lines, IReadOnlyList<ClassificationResult> results)
	{
		var sets = string.Join(',', lines.Select(l => l.Set).Distinct(StringComparer.Ordinal).OrderBy(s => s, StringComparer.Ordinal));
		Error($"autoWrongCensus set={sets} tracedLines={lines.Count} autoWrongLines={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(x => x.Relation, StringComparer.Ordinal)
			.ThenBy(x => x.Site, StringComparer.Ordinal);
		foreach (var (relation, site, count) in matrix)
		{
			Error($"{relation}\t{site}\t{count}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		Error($"other={other}/{results.Count} ({(results.Count == 0 ? 0.0 : other * 100.0 / results.Count):0.0}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField!)
			.Select(g => $"{g.Key}={g.Count()}");
		Error($"missingFields: {(missing.Any() ? string.Join(' ', missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		Error($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = 0;
		foreach (var r in reuseLines)
		{
			var line = lines.FirstOrDefault(l => l.HoldoutId == r.HoldoutId && l.LineIndex == r.LineIndex);
			var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
			if (atom is { LinkedIngredientId.Length: > 0 } && !string.IsNullOrWhiteSpace(atom.ParsedName))
			{
				var slug = IngredientLineParser.ComputeSlug(atom.ParsedName);
				if (!string.IsNullOrEmpty(slug) && !IngredientLineResolver.ShouldReuse(slug, atom.LinkedIngredientId))
				{
					reuseNameMismatch++;
				}
			}
		}
		Error($"reuse lines: {reuseLines.Count}, of which ShouldReuse(parsedName, linkedIngredientId) is false: {reuseNameMismatch}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		Error($"row-choice-tier: key higher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			Error($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(CancellationToken cancellationToken)
	{
		if (!File.Exists(_options.TracePath))
		{
			Error($"missing trace: '{_options.TracePath}'");
			return null;
		}

		var lines = new List<TraceLine>();
		try
		{
			await using var reader = new StreamReader(_options.TracePath);
			while (await reader.ReadLineAsync(cancellationToken) is { } json)
			{
				cancellationToken.ThrowIfCancellationRequested();
				if (json.Length == 0)
				{
					continue;
				}

				lines.Add(JsonSerializer.Deserialize<TraceLine>(json, JsonOptions)
					?? throw new InvalidOperationException("A trace line deserialized to null."));
			}
		}
		catch (JsonException ex)
		{
			Error($"unreadable trace JSON in '{_options.TracePath}': {ex.Message}");
			return null;
		}

		return lines;
	}

	private string? RefusedSet(IReadOnlyList<TraceLine> lines)
	{
		foreach (var line in lines)
		{
			if (!line.Set.Equals("debug", StringComparison.Ordinal) && !line.Set.Equals("batch", StringComparison.Ordinal))
			{
				return line.Set;
			}
		}

		return null;
	}

	private IReadOnlyList<CensusTsvRow>? ReadCensusTsv()
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			Error($"missing census TSV: '{_options.CensusTsvPath}'");
			return null;
		}

		var rows = new List<CensusTsvRow>();
		var header = File.ReadLines(_options.CensusTsvPath).First().Split('\t');
		var idCol = Array.IndexOf(header, "holdoutId");
		var idxCol = Array.IndexOf(header, "lineIndex");
		var blockerCol = Array.IndexOf(header, "blocker");
		var routeCol = Array.IndexOf(header, "route");
		if (idCol < 0 || idxCol < 0 || blockerCol < 0 || routeCol < 0)
		{
			Error($"census TSV '{_options.CensusTsvPath}' lacks holdoutId/lineIndex/blocker/route columns");
			return null;
		}

		foreach (var raw in File.ReadLines(_options.CensusTsvPath).Skip(1))
		{
			var cells = raw.Split('\t');
			if (cells.Length <= Math.Max(idCol, Math.Max(idxCol, Math.Max(blockerCol, routeCol))))
			{
				continue;
			}

			if (!cells[blockerCol].Equals("window", StringComparison.Ordinal)
				|| (!cells[routeCol].Equals("compound", StringComparison.Ordinal) && !cells[routeCol].Equals("other", StringComparison.Ordinal)))
			{
				continue;
			}

			rows.Add(new CensusTsvRow(cells[idCol], int.Parse(cells[idxCol])));
		}

		return rows;
	}

